contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 amount) public {
        uint256 senderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        require(amount <= senderBefore);

        bool ok = c.transfer(to, amount); if (__ESBMC_reverted()) return;

        assert(
            ok &&
            c.balanceOf(address(this)) == senderBefore - amount &&
            c.balanceOf(to) == toBefore + amount &&
            c.totalSupply() == supplyBefore
        );
    }

    receive() external payable {}
}

